let _stonePattern = null

function genStoneTexture() {
  const sw = 256, sh = 128
  const oc = wx.createCanvas()
  oc.width = sw; oc.height = sh
  const octx = oc.getContext('2d')
  const imgData = octx.createImageData(sw, sh)
  const d = imgData.data
  const seeds = []
  const tries = 200; const minDist = 22
  for (let i = 0; i < tries; i++) {
    const sx = 4 + Math.random() * (sw - 8); const sy = 4 + Math.random() * (sh - 8)
    let ok = true
    for (const s of seeds) { const dx = sx - s.x, dy = sy - s.y; if (dx * dx + dy * dy < minDist * minDist) { ok = false; break } }
    if (ok) seeds.push({ x: sx, y: sy, base: 38 + Math.random() * 45 | 0 })
  }
  for (let i = 0; i < d.length; i += 4) { d[i] = 14 + Math.random() * 6 | 0; d[i + 1] = 10 + Math.random() * 5 | 0; d[i + 2] = 8 + Math.random() * 4 | 0; d[i + 3] = 255 }
  for (let py = 0; py < sh; py++) { for (let px = 0; px < sw; px++) {
    let nearest = null, nearD2 = Infinity, nearD2b = Infinity
    for (const s of seeds) { const dx = px - s.x, dy = py - s.y; const nx = Math.sin(py * 0.08 + s.x * 0.1) * 6 + Math.sin(px * 0.06 + s.y * 0.12) * 4; const ny = Math.cos(px * 0.08 + s.y * 0.1) * 6 + Math.cos(py * 0.06 + s.x * 0.12) * 4; const d2 = (dx + nx) * (dx + nx) + (dy + ny) * (dy + ny); if (d2 < nearD2) { nearD2b = nearD2; nearD2 = d2; nearest = s } else if (d2 < nearD2b) nearD2b = d2 }
    if (nearD2b - nearD2 < 14 + Math.random() * 8) continue; if (!nearest) continue; const noise2 = Math.random() * 14 - 7 | 0; const v = Math.max(28, Math.min(115, nearest.base + noise2)); const idx = (py * sw + px) * 4; d[idx] = v + 10; d[idx + 1] = v + noise2 * 0.4; d[idx + 2] = v - 6 + noise2 * 0.2; d[idx + 3] = 255
  } }
  octx.putImageData(imgData, 0, 0)
  _stonePattern = octx.createPattern(oc, 'repeat')
}

