function drawRockRects(ox, oy, z, d, l) { const t = ui.bgTime; ctx.fillStyle = LAYERS[l].rock; for (const r of d.r) ctx.fillRect(ox + r[0] * z, oy + r[1] * z, r[2] * z, r[3] * z); ctx.fillStyle = LAYERS[l].vein; for (const r of d.v) ctx.fillRect(ox + r[0] * z, oy + r[1] * z, r[2] * z, r[3] * z); for (const s of d.sc) { const c = s[4], gv = 0.3 + 0.7 * Math.sin(t * 2 + l * 1.5 + s[0] * 0.3); if (c === '@') ctx.fillStyle = 'rgba(180,220,255,' + (0.15 * gv) + ')'; else if (c === '#') ctx.fillStyle = 'rgba(255,255,255,' + (0.15 * gv) + ')'; else if (c === '~') { const gv2 = 0.3 + 0.7 * Math.sin(t * 2.5 + l * 1.5); ctx.fillStyle = 'rgba(200,240,255,' + (0.12 * gv2) + ')' } else ctx.fillStyle = c; ctx.fillRect(ox + s[0] * z, oy + s[1] * z, s[2] * z, s[3] * z) } }

function drawRockCracks(ox, oy, z, d, p) { for (const ck of d.c) { if (p <= ck.t) continue; if (ck.lines) { ctx.save(); ctx.strokeStyle = ck.co; ctx.lineWidth = ck.lw || 1; for (const ln of ck.lines) { ctx.beginPath(); ctx.moveTo(ox + ln[0] * z, oy + ln[1] * z); for (let i = 2; i < ln.length; i += 2) ctx.lineTo(ox + ln[i] * z, oy + ln[i + 1] * z); ctx.stroke() }; ctx.restore() }; if (ck.fill) { ctx.fillStyle = ck.co; ctx.fillRect(ox + ck.fill[0] * z, oy + ck.fill[1] * z, ck.fill[2] * z, ck.fill[3] * z) } } }

function drawRockGlow(ox, oy, z, d, p, l) { if (p > 0.85 && d.g) { const gv = 0.3 + 0.7 * Math.sin(ui.bgTime * (1.5 + l * 0.5) + l * 2); ctx.fillStyle = d.g.co.replace('0.35', '' + (gv * 0.35)); ctx.fillRect(ox + d.g.x * z, oy + d.g.y * z, d.g.w * z, d.g.h * z) } }

function drawRock(x, y, s, l, p) { const z = s / 16, d = ROCK_D[l]; if (!d) return; drawRockRects(x, y, z, d, l); drawRockCracks(x, y, z, d, p); drawRockGlow(x, y, z, d, p, l) }

