function drawGachaHistory() { if (!ui.showGachaHistory) return; const pw = Math.min(300, W - 40), ph = Math.min(320, H - 60), px = (W - pw) / 2, py = (H - ph) / 2; ctx.fillStyle = 'rgba(0,0,0,0.7)'; ctx.fillRect(0, 0, W, H); ctx.fillStyle = '#1a1a2e'; ctx.fillRect(px, py, pw, ph); ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; ctx.strokeRect(px, py, pw, ph); ctx.fillStyle = '#FFD700'; ctx.font = PIXEL_FONT_M; ctx.textAlign = 'center'; ctx.fillText('抽卡记录', W / 2, py + 28); const his = state.gachaHistory, PER_PAGE = 10, totalPages = Math.max(1, Math.ceil(his.length / PER_PAGE)); if (ui.gachaHistoryPage >= totalPages) ui.gachaHistoryPage = totalPages - 1; if (ui.gachaHistoryPage < 0) ui.gachaHistoryPage = 0; const page = ui.gachaHistoryPage, startY2 = py + 40, rowH = 22; if (his.length === 0) { ctx.fillStyle = '#666'; ctx.font = PIXEL_FONT_S; ctx.textAlign = 'center'; ctx.fillText('暂无记录', W / 2, startY2 + 30) } else { ctx.save(); ctx.beginPath(); ctx.rect(px + 4, startY2, pw - 8, ph - 80); ctx.clip(); const startIdx = his.length - 1 - page * PER_PAGE, endIdx = Math.max(-1, startIdx - PER_PAGE); let displayIdx = 0; for (let i = startIdx; i > endIdx && i >= 0; i--) { const r = his[i]; if (!r) continue; const ry = startY2 + displayIdx * rowH, label = r.type === 'skin' ? '⚔ EX咖喱棒' : r.type === 'diamond' ? '💎 +' + r.amount : '💰 +' + r.amount; ctx.fillStyle = r.type === 'skin' ? '#FFD700' : '#AAA'; ctx.font = PIXEL_FONT_S; ctx.textAlign = 'left'; ctx.fillText(label, px + 10, ry + 14); displayIdx++ }; ctx.restore() }; const navY = py + ph - 60; ctx.fillStyle = '#FFD700'; ctx.font = PIXEL_FONT_S; ctx.textAlign = 'center'; ctx.fillText('第' + (page + 1) + '/' + totalPages + '页', px + pw / 2, navY + 20); if (totalPages > 1) { const triSize = 10, triY = navY + 6; if (page > 0) { const lx = px + pw / 2 - 55; ctx.fillStyle = '#FFD700'; ctx.beginPath(); ctx.moveTo(lx + triSize, triY); ctx.lineTo(lx, triY + triSize / 2); ctx.lineTo(lx + triSize, triY + triSize); ctx.closePath(); ctx.fill(); ui._gachaHistPrev = { x: lx - 8, y: triY - 8, w: triSize + 16, h: triSize + 16 } } else ui._gachaHistPrev = null; if (page < totalPages - 1) { const rx = px + pw / 2 + 55; ctx.fillStyle = '#FFD700'; ctx.beginPath(); ctx.moveTo(rx, triY); ctx.lineTo(rx + triSize, triY + triSize / 2); ctx.lineTo(rx, triY + triSize); ctx.closePath(); ctx.fill(); ui._gachaHistNext = { x: rx - 8, y: triY - 8, w: triSize + 16, h: triSize + 16 } } else ui._gachaHistNext = null } else { ui._gachaHistPrev = null; ui._gachaHistNext = null }; const by2 = py + ph - 36; pixelBtnBg(px + 40, by2, pw - 80, 28, true); ctx.fillStyle = '#FFF'; ctx.font = PIXEL_FONT_S; ctx.textAlign = 'center'; ctx.fillText('[关闭]', W / 2, by2 + 19); ui._gachaHistoryClose = { x: px + 40, y: by2, w: pw - 80, h: 28 } }

function doGacha(tenPull) { const pulls = tenPull ? 10 : 1, cost = tenPull ? (state.gachaFirst10 ? GACHA_COST_10_FIRST : GACHA_COST_10) : GACHA_COST_SINGLE; if (state.ore < cost) { addToast('钻石不足!'); return }; state.ore -= cost; if (tenPull) state.gachaFirst10 = false; let results = []; for (let i = 0; i < pulls; i++) { state.gachaPulls++; if (state.gachaPulls >= GACHA_PITY) { state.gachaPulls = 0; results.push({ type: 'skin' }); continue }; const r = fastRand(); if (r < 0.002) { state.gachaPulls = 0; results.push({ type: 'skin' }) } else if (r < 0.100) results.push({ type: 'diamond', amount: 120 }); else if (r < 0.200) results.push({ type: 'diamond', amount: 60 }); else if (r < 0.500) results.push({ type: 'gold', amount: 500 }); else results.push({ type: 'gold', amount: 200 }) }; ui.gachaAnim = { phase: 'mining', timer: 0, results, isTenPull: tenPull, goldParticles: [] }; save() }

function applyGachaResults(results) { for (const r of results) { state.gachaHistory.push({ type: r.type, amount: r.amount || 0, time: Date.now() }); if (state.gachaHistory.length > 100) state.gachaHistory.shift(); if (r.type === 'skin') { state.skins.pick[6] = 1; state.skins.pickEq = 6 } else if (r.type === 'diamond') state.ore += r.amount; else state.gold += r.amount } }

