function drawToasts() { for (const t of ui.toasts) { ctx.globalAlpha = Math.min(1, t.life * 2); ctx.fillStyle = '#FF4444'; ctx.font = PIXEL_FONT_L; ctx.textAlign = 'center'; ctx.fillText(t.text, W / 2, t.y) }; ctx.globalAlpha = 1; if (ui.debugTouch) { ctx.fillStyle = 'rgba(255,0,0,0.5)'; ctx.beginPath(); ctx.arc(ui.debugTouch.x, ui.debugTouch.y, 15, 0, Math.PI * 2); ctx.fill(); ctx.fillStyle = '#FF0'; ctx.font = PIXEL_FONT; ctx.textAlign = 'left'; ctx.fillText('触摸: ' + Math.round(ui.debugTouch.x) + ',' + Math.round(ui.debugTouch.y) + ' 按钮:' + (ui.btns ? ui.btns.length : 0), 5, H - 5); ui.debugTouch = null } }

function mineSwing() { playHit(); const l = LAYERS[state.layer], progGain = pickPower() / l.rockHP; ui.prog = Math.min(1, ui.prog + progGain); ui.swing = Math.max(0, ui.swing - 1); const cx = W / 2, groundY = Math.min(Math.round(H * GROUND_Y_RATIO), H - 180), rx = cx + 50, ry = groundY - 74; spawnP(rx + 45, ry + 40, null, 3); if (ui.prog >= 1) { ui.prog = 0; ui.rockShake = 1; playBreak(); const earned = Math.floor(l.rockGold * bonusMult()); state.gold += earned; if (l.rockOre > 0 && fastRand() < 0.6) state.ore += l.rockOre; const now = Date.now(), throttleOk = !ui._lastBreak || now - ui._lastBreak > 200; if (throttleOk) { const spd = swingSpeed(), scale = Math.min(1, 3 / Math.max(1, spd)); spawnRockBreak(rx, ry, 90, scale) }; ui._lastBreak = now; spawnCoin(rx + 45, ry, earned) } }

